    root.innerHTML=`<div class="page-title"><a href="#kullanici">← Kullanıcılara dön</a><button id="detail-refresh">Yenile</button></div><div class="detail-mobile-actions"><span>Hesap işlemleri</span><button id="mobile-actions" class="primary" aria-haspopup="dialog">İşlemler <span aria-hidden="true">↗</span></button></div><div class="detail-layout"><div><section class="panel"><div class="identity">${avatar(p)}<div><h1>${esc(p.nickname)}</h1><p>ID ${esc(p.display_id||'—')} · ${esc(p.country||'Ülke belirtilmemiş')}</p>${badges(p)}</div></div><div class="metrics">${[['Coin',d.wallet?.coin_balance],['Elmas',d.wallet?.diamond_balance],['Bayi stoku',d.dealer_balance],['Şikâyet',d.report_count]].map(([l,n])=>`<div class="metric"><span>${l}</span><strong>${num(n)}</strong></div>`).join('')}</div><div class="detail-tabs" role="tablist">${Object.entries(tabs).map(([key,label])=>`<button role="tab" id="detail-tab-${key}" tabindex="${key===state.tab?0:-1}" aria-selected="${key===state.tab}" aria-controls="detail-content" data-tab="${key}" class="${key===state.tab?'active':''}">${label}</button>`).join('')}</div><div id="detail-content" role="tabpanel" aria-labelledby="detail-tab-${state.tab}"></div></section><p class="note">Veri zamanı: ${esc(date(d.as_of))}. Cüzdan ve satın alma geçmişi tarih, tür ve referans ile sayfalanır. Tam ban geçmişi işlem kütüğündedir.</p></div><aside class="panel action-list" aria-label="Hesap işlemleri">${window.PuffyPhase2?.buttons(phase2Context())||''}${window.PuffyPhase3?.buttons(phase2Context())||''}${state.caps.owner?'<h3>Platform sahibi kasası</h3><button data-action="grant">Coin gönder</button><button data-action="clawback">Coin geri çek</button><button data-action="vip">VIP paketi ver</button><button data-action="ownerHistory">Kasa işlem geçmişi</button>':''}<p class="note">İşlem sonuçları sunucu tarafından doğrulanır. Coin/VIP için ödeme şifren gerekir.</p></aside></div>`;
    $('#detail-refresh').onclick=()=>detail(p.id);root.querySelectorAll('[data-tab]').forEach(b=>{b.onclick=()=>{state.tab=b.dataset.tab;renderDetail();$('#detail-tab-'+state.tab).focus();};b.onkeydown=e=>{const keys=Object.keys(tabs);let i=keys.indexOf(state.tab);if(e.key==='ArrowRight')i=(i+1)%keys.length;else if(e.key==='ArrowLeft')i=(i+keys.length-1)%keys.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=keys.length-1;else return;e.preventDefault();state.tab=keys[i];renderDetail();$('#detail-tab-'+state.tab).focus();};});$('#mobile-actions').onclick=openActionSheet;root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{document.querySelector('.actions-sheet')?.close();action(b.dataset.action);});bindAvatars(root);
    const c=$('#detail-content');
    if(window.PuffyGozlem?.tabs(phase2Context())[state.tab])window.PuffyGozlem.renderTab(state.tab,{...phase2Context(),root:c});
    if(window.PuffyPhase3?.tabs(phase2Context())[state.tab])window.PuffyPhase3.renderTab(state.tab,{...phase2Context(),root:c});
    if(window.PuffyPhase2?.tabs[state.tab])window.PuffyPhase2.renderTab(state.tab,{...phase2Context(),root:c});
    if(['transactions','purchases'].includes(state.tab))window.PuffyKapsam.renderFinance(state.tab,{...phase2Context(),root:c});
    if(state.tab==='account')c.innerHTML=`<dl class="key-values">${Object.entries({'UUID':p.id,'Kayıt tarihi':date(p.created_at),'Son görülme':date(p.last_seen_at),'E-posta':p.email??'Bu role kapalı','Ajans':d.agencies.map(x=>x.name+' · '+x.role).join(', ')||'Yok','Aile':d.families.map(x=>x.name+' · '+x.role).join(', ')||'Yok','VIP bitişi':date(p.vip_expires_at),'Hesap silme talebi':date(p.deletion_requested_at),'Anonimleştirme':p.deletion_requested_at?'14 günlük otomatik süreç; talep kullanıcı tarafından iptal edilebilir.':'Talep yok'}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;
