    if(state.tab==='moderation')c.innerHTML='<h3>Güncel platform banı</h3>'+table(['Başlangıç','Bitiş','Sebep'],d.bans.map(x=>[esc(date(x.created_at)),x.expires_at?esc(date(x.expires_at)):'Süresiz',esc(x.reason||'—')]))+'<h3>İşlem kütüğü</h3>'+table(['Zaman','Eylem','Yönetici','Ayrıntı'],d.moderation.map(x=>[esc(date(x.created_at)),esc(x.action),esc(x.actor_id||'Sistem'),`<details><summary>Göster</summary><pre>${esc(JSON.stringify({before:x.previous_state,after:x.new_state},null,2))}</pre></details>`]));
