  function reverseCoin(id,parent,p){const dlg=document.createElement('dialog');dlg.innerHTML=`<form><h2>Coin işlemini geri al</h2><p>${esc(p.nickname)} · İşlem ${esc(id)}</p><label for="reverse-reason">Sebep</label><textarea id="reverse-reason" name="reason" required minlength="3" maxlength="300"></textarea>${input('password','Ödeme şifresi','password','required autocomplete="off"')}<div class="dialog-error" role="alert"></div><div class="dialog-actions"><button type="button">Vazgeç</button><button type="submit" class="primary">Geri almayı onayla</button></div></form>`;document.body.append(dlg);dlg.showModal();dlg.addEventListener('close',()=>dlg.remove());dlg.querySelector('button[type=button]').onclick=()=>dlg.close();let busy=false;dlg.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dlg.querySelector('form').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.target);busy=true;dlg.querySelectorAll('button').forEach(b=>b.disabled=true);try{await rpc('platform_coin_geri_al',{p_hareket_id:id,p_neden:String(f.get('reason')).trim(),p_odeme_sifresi:f.get('password'),p_kismi:false});dlg.close();parent.close();toast('İşlem geri alındı.');if(state.route==='kullanici/'+p.id)detail(p.id);}catch(ex){dlg.querySelector('.dialog-error').textContent=errorText(ex);busy=false;dlg.querySelectorAll('button').forEach(b=>b.disabled=false);}};}
  async function staff(offset=0) {const root=$('#s-personel'),epoch=++state.epoch;root.innerHTML=title('Erişim yönetimi','Personel ve yetki','Mevcut üç rol slotunu kullanarak yetki ver veya kaldır.')+'<div class="panel" id="staff-list"></div>';const box=$('#staff-list');skeleton(box);try{const paged=state.caps.actions?.staff_paged===true,data=paged?await rpc('yonetim_personel_listesi',{p_limit:25,p_offset:offset}):await rpc('personel_listesi'),rows=paged?data.rows:data;if(epoch!==state.epoch)return;box.innerHTML=table(['Personel','Roller','Platform yöneticisi'],(rows||[]).map(p=>[`<div class="person">${avatar(p)}<div><a href="#kullanici/${esc(p.user_id)}">${esc(p.nickname)}</a><small>ID ${esc(p.display_id)}</small></div></div>`,[p.staff_role,p.staff_role_2,p.staff_role_3].filter(Boolean).map(r=>`<span class="tag">${esc(roleName(r))}</span>`).join(''),p.platform_admin?'Evet':'Hayır']));bindAvatars(box);if(paged){box.insertAdjacentHTML('beforeend',`<div class="pager"><span>${num(data.total)} personel</span><button data-staff-prev ${offset===0?'disabled':''}>Önceki</button><button data-staff-next ${offset+25>=data.total?'disabled':''}>Sonraki</button></div>`);box.querySelector('[data-staff-prev]').onclick=()=>staff(Math.max(0,offset-25));box.querySelector('[data-staff-next]').onclick=()=>staff(offset+25);}}catch(e){if(epoch===state.epoch)pending(box,e,()=>staff(offset));}}
